"""Saved November-16 checkpoint compatibility, copied from its bundled source diff."""

def install():
    import whole_body_tracking.tasks.tracking.mdp.rewards as rewards
    if not hasattr(rewards, "rolling_pass_recovery_arm_pose_l2"):
        exec('from __future__ import annotations\n\ndef rolling_pass_recovery_arm_pose_l2(\n    env: ManagerBasedRLEnv,\n    asset_cfg: SceneEntityCfg,\n    command_name: str = "motion",\n    ramp_s: float = 0.60,\n) -> torch.Tensor:\n    """Soft arm posture throughout waiting/return, independent of return distance.\n\n    Release at launch and retain the configured kick follow-through. Penalize\n    pose only: arm speed remains available for balance corrections.\n    """\n    command = _motion_command(env, command_name)\n    if command is None:\n        return torch.zeros(env.num_envs, device=env.device)\n    elapsed = (env.episode_length_buf - command._ball_kicked_frame).float() * float(env.step_dt)\n    alpha = ((elapsed - command.cfg.post_kick_follow_through_s) / max(ramp_s, 1e-8)).clamp(0.0, 1.0)\n    recovery = command._ball_kicked.float() * alpha.square() * (3.0 - 2.0 * alpha)\n    phase = (_waiting_stance_weight(env, command_name) + recovery).clamp(0.0, 1.0)\n    error = _init_like_joint_position_error(env.scene[asset_cfg.name], command, standing=True)\n    squared = error[:, asset_cfg.joint_ids].square()\n    return (0.5 * squared.mean(-1) + 0.5 * squared.amax(-1)) * phase\n\n', rewards.__dict__)
